namespace Ordering;

/// <summary>Handles product returns, the refunds they trigger and restocking.</summary>
public sealed class ReturnsHandler
{
    private readonly ReturnsWorkflow _returns;
    private readonly ReturnRefundService _refunds;
    private readonly ReturnRestockLedger _restock;

    public ReturnsHandler()
    {
        var processedReferences = new ProcessedReturnReferences();
        var refundJournal = new ReturnRefundJournal();
        _restock = new ReturnRestockLedger();
        _returns = new ReturnsWorkflow(processedReferences, _restock);
        _refunds = new ReturnRefundService(refundJournal);
    }

    public string ProcessReturn(Order order, Customer customer) =>
        _returns.Process(order, customer);

    public bool IsReturnable(Order order) =>
        _returns.IsReturnable(order);

    public decimal ComputeRefund(Order order) =>
        _refunds.Compute(order);

    public void LogRefund(Order order, decimal amount) =>
        _refunds.Log(order, amount);

    public int Restock(Order order) =>
        _restock.Restock(order);
}

internal sealed class ReturnsWorkflow
{
    private readonly ProcessedReturnReferences _processedReferences;
    private readonly ReturnRestockLedger _restock;

    public ReturnsWorkflow(
        ProcessedReturnReferences processedReferences,
        ReturnRestockLedger restock)
    {
        _processedReferences = processedReferences;
        _restock = restock;
    }

    public string Process(Order order, Customer customer)
    {
        if (string.IsNullOrEmpty(order.Reference))
            return "missing reference";
        if (_processedReferences.Contains(order.Reference))
            return "already processed";
        if (order.Lines.Count == 0)
            return "nothing to return";
        if (customer.Tier == CustomerTier.Blocked)
            return "customer blocked";

        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;
            if (line.Quantity > 100)
                return "quantity too high";

            _restock.AddPending(line.Sku, line.Quantity);
        }

        if (!_restock.HasEntries)
            return "no returnable lines";

        _processedReferences.Add(order.Reference);
        return "accepted";
    }

    public bool IsReturnable(Order order)
    {
        if (string.IsNullOrEmpty(order.Reference) || order.Lines.Count == 0)
            return false;
        if (_processedReferences.Contains(order.Reference))
            return false;

        int valid = 0;
        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;
            if (string.IsNullOrEmpty(line.Sku))
                continue;
            if (line.Quantity > 100)
                continue;
            if (line.Quantity >= 1 && line.Quantity <= 100)
                valid++;
        }

        return valid > 0;
    }
}

internal sealed class ProcessedReturnReferences
{
    private readonly HashSet<string> _references = new(StringComparer.Ordinal);

    public bool Contains(string reference) => _references.Contains(reference);

    public void Add(string reference) => _references.Add(reference);
}

internal sealed class ReturnRefundService
{
    private const decimal UnitRefund = 5m;
    private readonly ReturnRefundJournal _journal;

    public ReturnRefundService(ReturnRefundJournal journal)
    {
        _journal = journal;
    }

    public decimal Compute(Order order)
    {
        decimal refund = 0m;
        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;
            if (line.Quantity > 50)
                refund += line.Quantity * UnitRefund * 0.9m;
            else if (line.Quantity > 10)
                refund += line.Quantity * UnitRefund * 0.95m;
            else if (line.Quantity > 1)
                refund += line.Quantity * UnitRefund;
            else
                refund += UnitRefund;
        }

        if (_journal.Count > 1000 && refund > 0m)
            refund = Math.Min(refund, 10000m);
        if (refund > 5000m)
            refund *= 0.99m;

        return refund < 0m ? 0m : refund;
    }

    public void Log(Order order, decimal amount)
    {
        if (amount <= 0m)
            return;
        if (string.IsNullOrEmpty(order.Reference))
            return;

        if (_journal.Count == 0 || amount > 100m)
            _journal.Add($"{order.Reference}:{amount}");
        else if (amount > 50m)
            _journal.Add($"{order.Reference}:large:{amount}");
        else if (amount > 10m)
            _journal.Add($"{order.Reference}:mid:{amount}");
        else
            _journal.Add($"{order.Reference}:small:{amount}");

        if (_journal.Count > 500 && amount > 1000m)
            _journal.Add($"{order.Reference}:flag");
    }
}

internal sealed class ReturnRefundJournal
{
    private readonly List<string> _entries = new();

    public int Count => _entries.Count;

    public void Add(string entry) => _entries.Add(entry);
}

internal sealed class ReturnRestockLedger
{
    private readonly Dictionary<string, int> _pendingBySku = new(StringComparer.Ordinal);

    public bool HasEntries => _pendingBySku.Count != 0;

    public void AddPending(string sku, int quantity)
    {
        _pendingBySku[sku] = _pendingBySku.TryGetValue(sku, out var current)
            ? current + quantity
            : quantity;
    }

    public int Restock(Order order)
    {
        int moved = 0;
        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;

            var sku = line.Sku;
            if (string.IsNullOrEmpty(sku))
                continue;
            if (line.Quantity > 100)
                continue;

            if (_pendingBySku.TryGetValue(sku, out var pending) && pending > 0)
            {
                moved += pending;
                _pendingBySku[sku] = 0;
            }
            else if (line.Quantity > 50)
            {
                _pendingBySku[sku] = line.Quantity / 2;
            }
            else if (line.Quantity > 0)
            {
                _pendingBySku[sku] = line.Quantity;
            }

            if (moved > 100000)
                break;
        }

        return moved;
    }
}
